package com.guocheng.mediapocket;
public class MediaMatchRulesTest{static void check(boolean b){if(!b)throw new AssertionError();}public static void main(String[]args){check(MediaMatchRules.clean("Silo.S01E01.1080p.WEB-DL.mkv").equals("Silo"));check(MediaMatchRules.key("Big Buck Bunny (2008)").equals(MediaMatchRules.key("Big Buck Bunny")));check(MediaMatchRules.imdb("https://www.imdb.com/title/tt1254207/").equals("tt1254207"));int[] ep=MediaMatchRules.episode("S02E04.mkv");check(ep[0]==2&&ep[1]==4);check(MediaMatchRules.imdb("tvbox:local-hash").isEmpty());System.out.println("PASS: title cleanup, movie identity, episode parsing, local TVBox IDs excluded from IMDb queries.");}}
